@Bean
public Step processOrderStep(JobRepository jobRepository, PlatformTransactionManager txManager) {
    return new StepBuilder("processOrderStep", jobRepository)
        .<Order, ProcessedOrder>chunk(5, txManager)
        .reader(orderReader())
        .processor(orderProcessor())
        .writer(orderWriter())
        .faultTolerant()
        .skip(ValidationException.class).skipLimit(10)
        .retry(TransientDataAccessException.class).retryLimit(3)
        .build();
}
